mapper.select:
SELECT id, submission_id, attempts
FROM judge_tasks
WHERE id = #{taskId}

SELECT id, submission_id, attempts
FROM judge_tasks
WHERE status = 'ASSIGNED'
  AND lease_expires_at < #{now}
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE judge_tasks
   SET lease_expires_at = #{leaseUntil}, updated_at = #{now}
 WHERE worker_id = #{workerId}
   AND status = 'ASSIGNED'

UPDATE judge_tasks
   SET status = 'DONE', lease_expires_at = NULL, updated_at = #{now}
 WHERE id = #{taskId}

UPDATE judge_tasks
   SET status = 'DEAD', lease_expires_at = NULL, last_error = #{error}, updated_at = #{now}
 WHERE id = #{taskId}
